package main

import (
	"fmt"
	"strings"
)

type Options struct {
	All        bool
	Brief      bool
	Colorize   bool
	Completion string
	HasCompletion bool
	Conf       bool
	Directories bool
	Edit       string
	HasEdit    bool
	Help       bool
	Init       bool
	List       bool
	Path       string
	HasPath    bool
	Regex      bool
	Rm         string
	HasRm      bool
	Search     string
	HasSearch  bool
	Tag        string
	HasTag     bool
	Tags       bool
	Update     bool
	Version    bool
	Positional []string
}

func parseFlags(args []string) (Options, error) {
	var o Options
	i := 0
	// For handling "--" separator
	noMoreFlags := false
	for i < len(args) {
		arg := args[i]
		if noMoreFlags {
			o.Positional = append(o.Positional, arg)
			i++
			continue
		}
		if arg == "--" {
			noMoreFlags = true
			i++
			continue
		}
		if arg == "-" {
			o.Positional = append(o.Positional, arg)
			i++
			continue
		}
		if strings.HasPrefix(arg, "--") {
			// long flag
			eqIdx := strings.Index(arg, "=")
			var name, val string
			hasEq := false
			if eqIdx != -1 {
				name = arg[2:eqIdx]
				val = arg[eqIdx+1:]
				hasEq = true
			} else {
				name = arg[2:]
			}
			switch name {
			case "all":
				if hasEq {
					// bool flag with =? pflag would error? Let's check: --all=true? Need to test. For now, treat as error? Actually pflag allows --bool=value. But our bool flags: if hasEq, need to parse bool? Simpler: if hasEq, error? Let's see original: --all with =? Not tested. We'll handle: if hasEq, error unknown? Better to allow and parse.
					// For bool, if value is "true"/"false", set accordingly, else error?
					// To match pflag, --all=false would set false. We'll implement.
					b, err := parseBoolVal(val)
					if err != nil {
						return o, fmt.Errorf("invalid argument %q for \"--%s\" flag: %v", val, name, err)
					}
					o.All = b
				} else {
					o.All = true
				}
			case "brief":
				if hasEq {
					b, err := parseBoolVal(val)
					if err != nil {
						return o, fmt.Errorf("invalid argument %q for \"--%s\" flag: %v", val, name, err)
					}
					o.Brief = b
				} else {
					o.Brief = true
				}
			case "colorize":
				if hasEq {
					b, err := parseBoolVal(val)
					if err != nil {
						return o, fmt.Errorf("invalid argument %q for \"--%s\" flag: %v", val, name, err)
					}
					o.Colorize = b
				} else {
					o.Colorize = true
				}
			case "completion":
				if hasEq {
					o.Completion = val
					o.HasCompletion = true
				} else {
					if i+1 >= len(args) {
						return o, fmt.Errorf("flag needs an argument: --completion")
					}
					i++
					o.Completion = args[i]
					o.HasCompletion = true
				}
			case "conf":
				if hasEq {
					// bool? --conf doesn't take value, but if given =? Probably error? Let's treat as bool.
					b, err := parseBoolVal(val)
					if err != nil {
						return o, fmt.Errorf("invalid argument %q for \"--%s\" flag: %v", val, name, err)
					}
					o.Conf = b
				} else {
					o.Conf = true
				}
			case "directories":
				if hasEq {
					b, err := parseBoolVal(val)
					if err != nil {
						return o, fmt.Errorf("invalid argument %q for \"--%s\" flag: %v", val, name, err)
					}
					o.Directories = b
				} else {
					o.Directories = true
				}
			case "edit":
				if hasEq {
					o.Edit = val
					o.HasEdit = true
				} else {
					if i+1 >= len(args) {
						return o, fmt.Errorf("flag needs an argument: --edit")
					}
					i++
					o.Edit = args[i]
					o.HasEdit = true
				}
			case "help":
				if hasEq {
					b, err := parseBoolVal(val)
					if err != nil {
						return o, fmt.Errorf("invalid argument %q for \"--%s\" flag: %v", val, name, err)
					}
					o.Help = b
				} else {
					o.Help = true
				}
			case "init":
				if hasEq {
					b, err := parseBoolVal(val)
					if err != nil {
						return o, fmt.Errorf("invalid argument %q for \"--%s\" flag: %v", val, name, err)
					}
					o.Init = b
				} else {
					o.Init = true
				}
			case "list":
				if hasEq {
					b, err := parseBoolVal(val)
					if err != nil {
						return o, fmt.Errorf("invalid argument %q for \"--%s\" flag: %v", val, name, err)
					}
					o.List = b
				} else {
					o.List = true
				}
			case "path":
				if hasEq {
					o.Path = val
					o.HasPath = true
				} else {
					if i+1 >= len(args) {
						return o, fmt.Errorf("flag needs an argument: --path")
					}
					i++
					o.Path = args[i]
					o.HasPath = true
				}
			case "regex":
				if hasEq {
					b, err := parseBoolVal(val)
					if err != nil {
						return o, fmt.Errorf("invalid argument %q for \"--%s\" flag: %v", val, name, err)
					}
					o.Regex = b
				} else {
					o.Regex = true
				}
			case "rm":
				if hasEq {
					o.Rm = val
					o.HasRm = true
				} else {
					if i+1 >= len(args) {
						return o, fmt.Errorf("flag needs an argument: --rm")
					}
					i++
					o.Rm = args[i]
					o.HasRm = true
				}
			case "search":
				if hasEq {
					o.Search = val
					o.HasSearch = true
				} else {
					if i+1 >= len(args) {
						return o, fmt.Errorf("flag needs an argument: --search")
					}
					i++
					o.Search = args[i]
					o.HasSearch = true
				}
			case "tag":
				if hasEq {
					o.Tag = val
					o.HasTag = true
				} else {
					if i+1 >= len(args) {
						return o, fmt.Errorf("flag needs an argument: --tag")
					}
					i++
					o.Tag = args[i]
					o.HasTag = true
				}
			case "tags":
				if hasEq {
					b, err := parseBoolVal(val)
					if err != nil {
						return o, fmt.Errorf("invalid argument %q for \"--%s\" flag: %v", val, name, err)
					}
					o.Tags = b
				} else {
					o.Tags = true
				}
			case "update":
				if hasEq {
					b, err := parseBoolVal(val)
					if err != nil {
						return o, fmt.Errorf("invalid argument %q for \"--%s\" flag: %v", val, name, err)
					}
					o.Update = b
				} else {
					o.Update = true
				}
			case "version":
				if hasEq {
					b, err := parseBoolVal(val)
					if err != nil {
						return o, fmt.Errorf("invalid argument %q for \"--%s\" flag: %v", val, name, err)
					}
					o.Version = b
				} else {
					o.Version = true
				}
			default:
				return o, fmt.Errorf("unknown flag: --%s", name)
			}
			i++
			continue
		}
		if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			// short flags, possibly combined
			chars := arg[1:]
			j := 0
			for j < len(chars) {
				c := chars[j]
				switch c {
				case 'a':
					o.All = true
					j++
				case 'b':
					o.Brief = true
					j++
				case 'c':
					o.Colorize = true
					j++
				case 'd':
					o.Directories = true
					j++
				case 'e':
					// needs arg
					rest := chars[j+1:]
					if len(rest) > 0 {
						if rest[0] == '=' {
							rest = rest[1:]
						}
						o.Edit = rest
						o.HasEdit = true
						j = len(chars)
					} else {
						if i+1 >= len(args) {
							return o, fmt.Errorf("flag needs an argument: 'e' in -%s", chars)
						}
						i++
						o.Edit = args[i]
						o.HasEdit = true
						j = len(chars)
					}
				case 'h':
					o.Help = true
					j++
				case 'l':
					o.List = true
					j++
				case 'p':
					rest := chars[j+1:]
					if len(rest) > 0 {
						if rest[0] == '=' {
							rest = rest[1:]
						}
						o.Path = rest
						o.HasPath = true
						j = len(chars)
					} else {
						if i+1 >= len(args) {
							return o, fmt.Errorf("flag needs an argument: 'p' in -%s", chars)
						}
						i++
						o.Path = args[i]
						o.HasPath = true
						j = len(chars)
					}
				case 'r':
					o.Regex = true
					j++
				case 's':
					rest := chars[j+1:]
					if len(rest) > 0 {
						if rest[0] == '=' {
							rest = rest[1:]
						}
						o.Search = rest
						o.HasSearch = true
						j = len(chars)
					} else {
						if i+1 >= len(args) {
							return o, fmt.Errorf("flag needs an argument: 's' in -%s", chars)
						}
						i++
						o.Search = args[i]
						o.HasSearch = true
						j = len(chars)
					}
				case 't':
					rest := chars[j+1:]
					if len(rest) > 0 {
						if rest[0] == '=' {
							rest = rest[1:]
						}
						o.Tag = rest
						o.HasTag = true
						j = len(chars)
					} else {
						if i+1 >= len(args) {
							return o, fmt.Errorf("flag needs an argument: 't' in -%s", chars)
						}
						i++
						o.Tag = args[i]
						o.HasTag = true
						j = len(chars)
					}
				case 'T':
					o.Tags = true
					j++
				case 'u':
					o.Update = true
					j++
				case 'v':
					o.Version = true
					j++
				default:
					return o, fmt.Errorf("unknown shorthand flag: '%c' in -%s", c, chars)
				}
			}
			i++
			continue
		}
		// positional
		o.Positional = append(o.Positional, arg)
		i++
	}
	return o, nil
}

func parseBoolVal(s string) (bool, error) {
	switch s {
	case "true", "1", "t", "T", "TRUE", "True":
		return true, nil
	case "false", "0", "f", "F", "FALSE", "False":
		return false, nil
	default:
		return false, fmt.Errorf("strconv.ParseBool: parsing %q: invalid syntax", s)
	}
}
