// YAML parsing helpers
func isBoolStr(s string) (bool, bool) {
	low := strings.ToLower(s)
	switch low {
	case "y", "yes", "true", "on":
		// Note: "y" true, "yes" true, etc. But need to handle case variations: Y, Yes, YES, etc. ToLower covers.
		// Also single "y"/"n"? low is lower, so "y" matches, "n" handled below.
		return true, true
	case "n", "no", "false", "off":
		return false, true
	}
	// Also handle "True"/"False" etc. already via ToLower.
	// What about "TRUE"/"FALSE"? covered.
	return false, false
}

func yamlTagForScalar(s string, quoted bool, line string) string {
	if quoted {
		return "!!str"
	}
	// check null? "~", "null", "Null", "NULL", ""? For our purposes, empty is null.
	if s == "" || s == "~" || strings.EqualFold(s, "null") {
		return "!!null"
	}
	if _, ok := isBoolStr(s); ok {
		return "!!bool"
	}
	// check int? optional +/- and digits
	t := s
