func stripQuotes(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'') {
			return s[1 : len(s)-1]
		}
	}
	return s
}
func isQuoted(s string) bool {
	s = strings.TrimSpace(s)
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'') {
			return true
		}
	}
	return false
}
func stripInlineComment(s string) string {
	// Find # not inside quotes
	inSingle := false
	inDouble := false
	for i, ch := range s {
		if ch == '\'' && !inDouble {
			// handle escaped ''? For simplicity, toggle
			inSingle = !inSingle
		} else if ch == '"' && !inSingle {
			inDouble = !inDouble
		} else if ch == '#' && !inSingle && !inDouble {
			// check if preceded by space or at start? YAML requires space before # for comment? For simplicity, if # and (i==0 or s[i-1]==' ' or s[i-1]=='\t') then comment
			if i == 0 || s[i-1] == ' ' || s[i-1] == '\t' {
				return strings.TrimSpace(s[:i])
			}
		}
	}
	return s
}
