func isYes(s string) bool {
	t := strings.TrimSpace(s)
	if t == "" {
		return true
	}
	if len(t) == 1 {
		c := t[0]
		if c == 'y' || c == 'Y' {
			return true
		}
		if c == 'n' || c == 'N' {
			return false
		}
		return false
	}
	// Multi-char? Original treats "yes", "Yx", etc. as no (false). So only single y/Y or empty is yes, all else no.
	return false
}

