}

func actionRm(cfg *Config, sheets []Sheet, opts Options) int {
	title := opts.Rm
	if opts.HasPath {
		found := false
		for _, cp := range cfg.Cheatpaths {
			if cp.Name == opts.Path {
				found = true
				break
			}
		}
		if !found {
			fmt.Fprintf(os.Stderr, "invalid option --path: cheatpath does not exist: %s\n", opts.Path)
			return 1
		}
	}
	var matched []Sheet
	for _, s := range sheets {
		if s.Title != title {
			continue
		}
		if opts.HasPath && s.CheatpathName != opts.Path {
			continue
		}
		if opts.HasTag {
			found := false
			for _, t := range s.Tags {
				if t == opts.Tag {
					found = true
					break
				}
			}
			if !found {
				continue
			}
		}
		matched = append(matched, s)
	}
	if len(matched) == 0 {
		fmt.Fprintf(os.Stderr, "No cheatsheet found for '%s'.\n", title)
		return 2
	}
	// Choose most local
	maxIdx := -1
	var chosen Sheet
	for _, s := range matched {
		idx := -1
		for i, cp := range cfg.Cheatpaths {
			if cp.Name == s.CheatpathName {
				idx = i
				break
			}
		}
		if idx > maxIdx {
			maxIdx = idx
			chosen = s
		}
	}
	// Check readonly
	for _, cp := range cfg.Cheatpaths {
		if cp.Name == chosen.CheatpathName && cp.Readonly {
			fmt.Fprintf(os.Stderr, "cheatsheet '%s' is read-only.\n", title)
			return 1
		}
	}
	if err := os.Remove(chosen.Path); err != nil {
		fmt.Fprintf(os.Stderr, "failed to remove cheatsheet: %v\n", err)
		return 1
	}
	return 0
}

func actionUpdate(cfg *Config, opts Options) int {
	// Filter by path if specified
	var targets []Cheatpath
	if opts.HasPath {
		found := false
		for _, cp := range cfg.Cheatpaths {
			if cp.Name == opts.Path {
				found = true
				targets = append(targets, cp)
				break
			}
		}
		if !found {
			fmt.Fprintf(os.Stderr, "invalid option --path: cheatpath does not exist: %s\n", opts.Path)
			return 1
		}
	} else {
		targets = cfg.Cheatpaths
	}
	// For each, check if git repo (contains .git dir?)
	exitCode := 0
	for _, cp := range targets {
		gitDir := filepath.Join(cp.Path, ".git")
		if _, err := os.Stat(gitDir); os.IsNotExist(err) {
			fmt.Fprintf(os.Stdout, "%s: skipped (not a git repository)\n", cp.Name)
			continue
		}
		// Try to pull via git command
		cmd := exec.Command("git", "-C", cp.Path, "pull", "--ff-only")
		out, err := cmd.CombinedOutput()
		_ = out
		if err != nil {
			// Check for remote not found? Original for work without remote gave "work: error (remote not found)" to stderr.
			// How to detect remote not found vs other errors? For git pull without remote, git output contains "There is no tracking information..." or "No remote..."? But original message is "error (remote not found)" – that's go-git message, not git command message.
			// To match, we need to detect if no remote configured, then print "error (remote not found)" to stderr.
			// Otherwise, print "error (...)"? Let's check what git pull without remote gives: it exits 1 with "There is no tracking information for the current branch..." etc.
			// But original gives "remote not found". So we need to check remotes.
			// Simplify: check if `git -C <path> remote` returns empty => remote not found.
			remCmd := exec.Command("git", "-C", cp.Path, "remote")
			remOut, _ := remCmd.Output()
			if strings.TrimSpace(string(remOut)) == "" {
				fmt.Fprintf(os.Stderr, "%s: error (remote not found)\n", cp.Name)
				exitCode = 1
				continue
			}
			// For other errors, print "error (...)"? What does original do for other git errors? Probably "error (...)" with details. For now, print generic.
			fmt.Fprintf(os.Stderr, "%s: error (%v)\n", cp.Name, strings.TrimSpace(string(out)))
			exitCode = 1
			continue
		}
		fmt.Fprintf(os.Stdout, "%s: ok\n", cp.Name)
	}
	return exitCode
}
