{"command": "cat > util.go <<'GOEOF'
package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

func writeThroughPager(content string, pager string) error {
	if strings.TrimSpace(pager) == "" {
		fmt.Fprint(os.Stdout, content)
		return nil
	}
	parts := strings.Fields(pager)
	if len(parts) == 0 {
		fmt.Fprint(os.Stdout, content)
		return nil
	}
	cmd := exec.Command(parts[0], parts[1:]...)
	cmd.Stdin = strings.NewReader(content)
	var out bytes.Buffer
	var errBuf bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &errBuf
	err := cmd.Run()
	if err != nil {
		if _, ok := err.(*exec.Error); ok {
			return fmt.Errorf("failed to write to pager: exec: %q: executable file not found in $PATH", parts[0])
		}
		if _, ok := err.(*exec.ExitError); ok {
			return fmt.Errorf("failed to write to pager: %v", err)
		}
		return fmt.Errorf("failed to write to pager: %v", err)
	}
	fmt.Fprint(os.Stdout, out.String())
	if errBuf.Len() > 0 {
		fmt.Fprint(os.Stderr, errBuf.String())
	}
	return nil
}

func isTerminal() bool {
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func shouldColorize(cfg *Config, force bool) bool {
	if force {
		return true
	}
	if cfg.Colorize && isTerminal() {
		return true
	}
	return false
}

func colorizeBody(body string, syntax, style, formatter string) string {
	if body == "" {
		return ""
	}
	lines := strings.Split(body, "\n")
	var out []string
	for i, l := range lines {
		if i == len(lines)-1 && l == "" {
			continue
		}
		out = append(out, colorizeSingleLine(l, syntax, style, formatter))
	}
	if len(out) == 0 {
		return ""
	}
	return strings.Join(out, "\n") + "\n"
}

func colorizePlain(body string, style, formatter string) string {
	return colorizeBody(body, "", style, formatter)
}

func colorizeSingleLine(line, syntax, style, formatter string) string {
	if formatter == "terminal" || formatter == "" {
		return "\x1b[1m\x1b[37m" + line + "\x1b[0m"
	}
	if formatter == "terminal16m" {
		return "\x1b[38;2;248;248;242m" + line + "\x1b[0m"
	}
	// terminal256
	if syntax == "markdown" {
		return "\x1b[38;5;231m" + line + "\x1b[0m"
	}
	if syntax != "" {
		low := strings.ToLower(syntax)
		if low == "markdown" {
			return "\x1b[38;5;231m" + line + "\x1b[0m"
		}
		known := map[string]bool{"bash": true, "sh": true, "shell": true, "python": true, "javascript": true, "js": true, "go": true, "java": true, "c": true, "cpp": true, "ruby": true, "rust": true, "yaml": true, "json": true, "xml": true, "html": true, "css": true, "markdown": true}
		if !known[low] {
			return "\x1b[38;5;231m" + line + "\x1b[0m"
		}
	}
	trimmed := strings.TrimSpace(line)
	if strings.HasPrefix(trimmed, "#") {
		return "\x1b[38;5;242m" + line + "\x1b[0m\x1b[38;5;231m\x1b[0m"
	}
	return "\x1b[38;5;231m" + line + "\x1b[0m"
}

func colorizeSearchHeader(title, cheatpath string) string {
	return fmt.Sprintf("%s \x1b[2m(%s)\x1b[0m", title, cheatpath)
}
